import { readFileSync } from "node:fs";

const pkg = JSON.parse(readFileSync(new URL("./package.json", import.meta.url), "utf8"));
const packageConfig = pkg["lint-staged"];

function quote(file) {
  return `'${file.replaceAll("'", "'\\''")}'`;
}

/**
 * `src/routeTree.gen.ts` is regenerated by TanStack Start, including the
 * `eslint-disable` header. ESLint --fix treats that header as an unused
 * directive and deletes it. Leave the generated file to the generator.
 */
const generatedRouteTree = "src/routeTree.gen.ts";

export default {
  "*.{ts,tsx}": (filenames) => {
    const linted = filenames.filter((file) => !file.endsWith(generatedRouteTree));
    const commands = [];
    if (linted.length > 0) {
      const list = linted.map(quote).join(" ");
      commands.push(`prettier --write ${list}`, `eslint --fix ${list}`);
    }
    commands.push(packageConfig["*.{ts,tsx}"][2]);
    return commands;
  },
  "*.{js,jsx,mjs,cjs,json,css,md,html,yml,yaml}":
    packageConfig["*.{js,jsx,mjs,cjs,json,css,md,html,yml,yaml}"],
};
